package ru.mtuci.drivenext.presentation.landlord
import android.content.Intent; import android.net.Uri; import android.os.Bundle; import android.widget.ImageView; import android.widget.LinearLayout; import androidx.activity.result.contract.ActivityResultContracts; import androidx.appcompat.app.AppCompatActivity; import ru.mtuci.drivenext.databinding.ActivityCarPhotosBinding
class CarPhotosActivity:AppCompatActivity(){private lateinit var b:ActivityCarPhotosBinding;private val photos=mutableListOf<Uri>();private val picker=registerForActivityResult(ActivityResultContracts.GetMultipleContents()){items->photos.clear();photos.addAll(items.take(5));render()};override fun onCreate(s:Bundle?){super.onCreate(s);b=ActivityCarPhotosBinding.inflate(layoutInflater);setContentView(b.root);b.backButton.setOnClickListener{finish()};b.chooseButton.setOnClickListener{picker.launch("image/*")};b.nextButton.setOnClickListener{startActivity(Intent(this,CarAddedActivity::class.java).addFlags(Intent.FLAG_ACTIVITY_CLEAR_TOP))}}private fun render(){b.photoStrip.removeAllViews();photos.forEach{uri->b.photoStrip.addView(ImageView(this).apply{setImageURI(uri);scaleType=ImageView.ScaleType.CENTER_CROP},LinearLayout.LayoutParams(0,110.dp,1f).apply{marginEnd=6.dp})};b.counter.text="${photos.size} / 5";b.nextButton.isEnabled=photos.isNotEmpty()}private val Int.dp:Int get()=(this*resources.displayMetrics.density).toInt()}
